#include <stdio.h>

/* teste do desafio idade-na-tela — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste: freopen manda o stdout
   para o arquivo temporario, o teste chama a funcao do aluno e le de volta. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void idadeNaTela(void);

SM_TEST(a_idade_na_frase) {
    freopen("sm_saida.tmp", "w", stdout);
    idadeNaTela();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha da idade", linha, "a idade e 20 anos\n",
              "a frase leva o valor guardado em idade no lugar do %d");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na primeira linha: nenhuma linha extra e aceita");
    fclose(f);
}

